mkdir bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Globally unique name for the Terraform state bucket."
}
EOF
cat > main.tf <<'EOF'
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "backend_config_command" {
  value = "terraform init -backend-config=\"bucket=${aws_s3_bucket.state.id}\" -backend-config=\"region=${var.region}\""
}
EOF
cat > ../backend.tf <<'EOF'
# Partial configuration: the bucket and region are supplied at init time
# (see README), since backend blocks cannot reference variables.
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > ../.gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfvars
crash.log
EOF
cat > ../README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

## State

State lives in a versioned, KMS-encrypted, non-public S3 bucket with native S3 locking
(`use_lockfile`, Terraform >= 1.10), so the whole team can run `plan` and `apply`. No DynamoDB
table is needed.

The state contains the uploader's secret access key. Restrict access to the state bucket to the
people who may read that key (`s3:GetObject`, plus `kms:Decrypt` on the default `aws/s3` key or
a CMK of your choosing).

### One-time bootstrap

`bootstrap/` creates the state bucket. Its own state is local (it can't live in the bucket it
creates); run it once by one person and keep the small `bootstrap/terraform.tfstate` safe, or
migrate it into the bucket afterwards with a `backend "s3"` block using a different key.

```sh
cd bootstrap
terraform init
terraform apply -var state_bucket_name=<globally-unique-bucket-name>
```

### Migrating the existing local state

The person who holds the current `terraform.tfstate` runs, from the repo root:

```sh
terraform init -migrate-state \
  -backend-config="bucket=<state-bucket>" -backend-config="region=eu-north-1"
```

Answer `yes` to copy the state. Verify with `terraform plan` (expect no changes), then delete the
local `terraform.tfstate*` files.

## Usage (everyone else)

Credentials need `s3:ListBucket` on the bucket and `s3:GetObject`/`PutObject`/`DeleteObject` on
`reports/*` (the lock file is `reports/terraform.tfstate.tflock`).

```sh
terraform init \
  -backend-config="bucket=<state-bucket>" -backend-config="region=eu-north-1"
terraform plan
terraform apply
```

`terraform output` (including `-raw uploader_secret_access_key`) now reads from the shared state.
